  format: { type: 'object', required: ['capabilities','actors','processes','services'], properties: { capabilities: { type: 'array' }, actors: { type: 'array' }, processes: { type: 'array' }, services: { type: 'array' }, relationships: { type: 'array' } } },
  options: { temperature: $('Initialize Parameters').first().json.ollamaTemperature, seed: $('Initialize Parameters').first().json.ollamaSeed }
} }}

