const raw = $json.message?.content;
let arch; try { arch = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, businessArch: null } }]; }
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
return [{ json: { valid: true, businessArch: arch, businessArchHash: fnv1a(JSON.stringify(arch)) } }];

