const raw = $json.message?.content;
let arch; try { arch = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, infraArch: null } }]; }
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
return [{ json: { valid: true, infraArch: arch, infraArchHash: fnv1a(JSON.stringify(arch)) } }];

// Convert all architecture layers to separate ArchiMate XML files + combined
const ctx = $('Pass Context').first().json;
const biz = $('Validate Business Arch').first().json.businessArch || {};
const app = $('Validate Application Arch').first().json.applicationArch || {};
const data = $('Validate Data Arch').first().json.dataArch || {};
const infra = $('Validate Infrastructure Arch').first().json.infraArch || {};

const uuid = () => 'id-' + Math.random().toString(36).substr(2, 9);
const getName = (item) => {
  if (typeof item === 'string') return item;
  if (item && typeof item === 'object') {
    if (item.name) return String(item.name);
    if (item.title) return String(item.title);
    if (item.id) return String(item.id);
    const keys = Object.keys(item);
    if (keys.length > 0) return String(item[keys[0]]);
    return 'Unknown';
  }
  return String(item || 'Unknown');
};
const escXml = (s) => String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };

// Generate element with consistent ID based on type+name (for deduplication)
const elemId = (type, name) => 'id-' + fnv1a(type + ':' + name);
const elem = (type, archType, name) => `<element xsi:type="archimate:${archType}" id="${elemId(type, getName(name))}" name="${escXml(getName(name))}"/>`;

// Build separate layer elements
let bizElems = '';
for (const cap of (biz.capabilities || [])) bizElems += elem('cap', 'Capability', cap) + '\n';
for (const actor of (biz.actors || [])) bizElems += elem('actor', 'BusinessActor', actor) + '\n';
for (const proc of (biz.processes || [])) bizElems += elem('proc', 'BusinessProcess', proc) + '\n';
for (const svc of (biz.services || [])) bizElems += elem('svc', 'BusinessService', svc) + '\n';

let appElems = '';
for (const comp of (app.components || [])) appElems += elem('comp', 'ApplicationComponent', comp) + '\n';
for (const iface of (app.interfaces || [])) appElems += elem('iface', 'ApplicationInterface', iface) + '\n';
for (const obj of (app.dataObjects || [])) appElems += elem('dataobj', 'DataObject', obj) + '\n';

let dataElems = '';
for (const ent of (data.dataEntities || [])) dataElems += elem('entity', 'DataObject', ent) + '\n';
for (const db of (data.databases || [])) dataElems += elem('db', 'Artifact', db) + '\n';
for (const flow of (data.dataFlows || [])) dataElems += elem('flow', 'DataObject', flow) + '\n';

let techElems = '';
for (const node of (infra.nodes || [])) techElems += elem('node', 'Node', node) + '\n';
for (const net of (infra.networks || [])) techElems += elem('net', 'CommunicationNetwork', net) + '\n';
for (const dep of (infra.deployments || [])) techElems += elem('deploy', 'SystemSoftware', dep) + '\n';
for (const art of (infra.artifacts || [])) techElems += elem('artifact', 'Artifact', art) + '\n';

// Template for individual layer files
const layerXml = (layer, folder, elems) => `<?xml version="1.0" encoding="UTF-8"?>\n<archimate:model xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:archimate="http://www.archimatetool.com/archimate" name="${ctx.projectName} - ${layer}" id="${uuid()}">\n  <folder name="${folder}" type="${folder.toLowerCase()}">\n${elems}  </folder>\n</archimate:model>`;

// Generate separate layer XMLs
const businessXml = layerXml('Business Architecture', 'Business', bizElems);
const applicationXml = layerXml('Application Architecture', 'Application', appElems);
const dataXml = layerXml('Data Architecture', 'Data', dataElems);
const technologyXml = layerXml('Technology Architecture', 'Technology', techElems);

// Generate combined full.archimate
const fullXml = `<?xml version="1.0" encoding="UTF-8"?>\n<archimate:model xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:archimate="http://www.archimatetool.com/archimate" name="${ctx.projectName}" id="${uuid()}">\n  <folder name="Business" type="business">\n${bizElems}  </folder>\n  <folder name="Application" type="application">\n${appElems}  </folder>\n  <folder name="Data" type="data">\n${dataElems}  </folder>\n  <folder name="Technology" type="technology">\n${techElems}  </folder>\n  <folder name="Relations" type="relations">\n  </folder>\n</archimate:model>`;

return [{ json: { ...ctx, businessXml, applicationXml, dataXml, technologyXml, fullXml, fullXmlHash: fnv1a(fullXml) } }];

const ctx = $('Pass Context').first().json;
const archDir = ctx.projectSlug + '-docs/architecture';
return [{ json: { success: true, jobId: ctx.jobId, projectSlug: ctx.projectSlug, stage: 'architecture', archPaths: { business: archDir + '/business.archimate', application: archDir + '/application.archimate', data: archDir + '/data.archimate', technology: archDir + '/technology.archimate', full: archDir + '/full.archimate', orgFull: 'org-architecture/full.archimate' } } }];
